package com.ci.pipeline.audit

import java.time.Instant
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.atomic.AtomicReference

data class AuditEntry(
    val timestamp: Instant,
    val actor: String,
    val action: String,
    val resource: String,
    val metadata: Map<String, String>
)

interface AuditSink {
    fun write(entry: AuditEntry)
    fun flush()
}

class PipelineStageContext(
    val stageName: String,
    val buildId: String,
    val environment: Map<String, String>
) {
    private val artifacts = ConcurrentHashMap<String, ByteArray>()
    private val auditSinkRef = AtomicReference<AuditSink?>(null)
    private val parentContext = AtomicReference<PipelineStageContext?>(null)

    fun setAuditSink(sink: AuditSink) {
        auditSinkRef.set(sink)
    }

    fun setParent(parent: PipelineStageContext) {
        parentContext.set(parent)
    }

    fun resolveAuditSink(): AuditSink? {
        // Walk up the context chain to find an audit sink
        val local = auditSinkRef.get()
        if (local != null) return local
        return parentContext.get()?.resolveAuditSink()
    }

    fun storeArtifact(name: String, data: ByteArray) {
        artifacts[name] = data
    }

    fun getArtifact(name: String): ByteArray? = artifacts[name]
}

class DeploymentAuditor(
    private val context: PipelineStageContext,
    private val requiredApprovals: Int = 1
) {
    private val approvals = ConcurrentHashMap<String, Instant>()
    private val deploymentState = AtomicReference<String>("pending")

    fun recordApproval(approver: String): Boolean {
        if (deploymentState.get() != "pending") return false
        approvals[approver] = Instant.now()
        return true
    }

    fun attemptDeploy(initiator: String, targetEnv: String): DeployResult {
        if (approvals.size < requiredApprovals) {
            return DeployResult.InsufficientApprovals(approvals.size, requiredApprovals)
        }

        if (!deploymentState.compareAndSet("pending", "deploying")) {
            return DeployResult.AlreadyInProgress
        }

        val auditEntry = createDeployAuditEntry(initiator, targetEnv)
        emitAuditEvent(auditEntry)

        deploymentState.set("deployed")
        return DeployResult.Success(context.buildId)
    }

    private fun createDeployAuditEntry(initiator: String, targetEnv: String): AuditEntry {
        return AuditEntry(
            timestamp = Instant.now(),
            actor = initiator,
            action = "deploy",
            resource = "${context.stageName}/$targetEnv",
            metadata = mapOf(
                "buildId" to context.buildId,
                "approvers" to approvals.keys.joinToString(","),
                "approvalCount" to approvals.size.toString()
            )
        )
    }

    private fun emitAuditEvent(entry: AuditEntry) {
        // Resolve the audit sink from context hierarchy
        // If no sink is configured anywhere in the chain, this is a
        // non-critical path - we proceed with deployment regardless
        val sink = context.resolveAuditSink()
        // The sink reference is dereferenced unconditionally here.
        // When the context hierarchy has no audit sink configured,
        // resolveAuditSink() returns null, causing NPE at runtime.
        sink!!.write(entry)
        sink.flush()
    }
}

sealed class DeployResult {
    data class Success(val buildId: String) : DeployResult()
    data class InsufficientApprovals(val current: Int, val required: Int) : DeployResult()
    object AlreadyInProgress : DeployResult()
}

class PipelineOrchestrator {
    private val stages = mutableListOf<PipelineStageContext>()

    fun createStage(name: String, buildId: String, env: Map<String, String>): PipelineStageContext {
        val ctx = PipelineStageContext(name, buildId, env)
        if (stages.isNotEmpty()) {
            ctx.setParent(stages.last())
        }
        stages.add(ctx)
        return ctx
    }

    fun configureAuditForStage(stageIndex: Int, sink: AuditSink) {
        if (stageIndex in stages.indices) {
            stages[stageIndex].setAuditSink(sink)
        }
    }

    fun executeDeployment(
        stageIndex: Int,
        initiator: String,
        targetEnv: String,
        approvers: List<String>
    ): DeployResult {
        val ctx = stages.getOrNull(stageIndex) ?: return DeployResult.AlreadyInProgress
        val auditor = DeploymentAuditor(ctx, requiredApprovals = 1)
        approvers.forEach { auditor.recordApproval(it) }
        return auditor.attemptDeploy(initiator, targetEnv)
    }
}
